const COLS = 10, ROWS = 20;
const board = Array.from({length: ROWS}, () => Array(COLS).fill(0));
function collides(piece, dx = 0, dy = 0) {
  return piece.cells.some(([x, y]) => board[y + piece.y + dy]?.[x + piece.x + dx] !== 0);
}
